package com.bank.rollout;

// Models the database schema. A forward migration adds a NOT NULL column.
// This state is OUTSIDE the Deployment revision — rollback cannot revert it.
public class SchemaState {
    private boolean feeCurrencyColumnExists = false; // added by v6 migration

    public void applyV6Migration() { feeCurrencyColumnExists = true; }
    public boolean hasFeeCurrencyColumn() { return feeCurrencyColumnExists; }

    // Old v5 code does NOT set fee_currency; insert fails if column is NOT NULL.
    public boolean insertTradeFromOldCode() {
        return !feeCurrencyColumnExists; // true=success, false=constraint violation
    }
}
