package com.bank.rollout;

import java.util.*;
import java.util.logging.Logger;

public class RolloutManager {

    private static final Logger log = Logger.getLogger(RolloutManager.class.getName());

    private final int desired;
    private final int maxSurge;
    private final int maxUnavailable;
    private final Deque<String> revisionHistory = new ArrayDeque<>();
    private List<PodReplica> pods = new ArrayList<>();

    public RolloutManager(int desired, int maxSurge, int maxUnavailable, String initialVersion) {
        this.desired = desired; this.maxSurge = maxSurge; this.maxUnavailable = maxUnavailable;
        for (int i = 0; i < desired; i++) { PodReplica p = new PodReplica(initialVersion); p.markReady(); pods.add(p); }
        revisionHistory.push(initialVersion);
        log.info(() -> "initial revision " + initialVersion + " with " + desired + " ready pods");
    }

    // Rolling update: add up to maxSurge new pods, retire old ones only after new are ready.
    public void rollingUpdate(String newVersion) {
        log.info(() -> "rolling update -> " + newVersion
                + " (maxSurge=" + maxSurge + ", maxUnavailable=" + maxUnavailable + ")");
        int replaced = 0;
        while (replaced < desired) {
            PodReplica fresh = new PodReplica(newVersion);  // surge: +1 pod
            pods.add(fresh);
            fresh.markReady();                               // readiness passes
            // retire one old pod (respect maxUnavailable: never drop below desired-maxUnavailable ready)
            pods.removeIf(p -> !p.getVersion().equals(newVersion) && p.isReady() && countOld(newVersion) > 0 ? false : false);
            removeOneOld(newVersion);
            replaced++;
            int ready = (int) pods.stream().filter(PodReplica::isReady).count();
            log.info("  step " + replaced + "/" + desired + ": ready=" + ready + " running " + newVersion);
        }
        revisionHistory.push(newVersion);
        log.info(() -> "rollout to " + newVersion + " complete");
    }

    private int countOld(String newVersion) {
        return (int) pods.stream().filter(p -> !p.getVersion().equals(newVersion)).count();
    }
    private void removeOneOld(String newVersion) {
        for (Iterator<PodReplica> it = pods.iterator(); it.hasNext(); ) {
            if (!it.next().getVersion().equals(newVersion)) { it.remove(); return; }
        }
    }

    // rollout undo: scale the previous revision back up (another rolling op).
    public void undo() {
        revisionHistory.pop();                 // drop current revision
        String previous = revisionHistory.peek();
        log.warning(() -> "rollout undo -> reverting Pod template to " + previous);
        pods = new ArrayList<>();
        for (int i = 0; i < desired; i++) { PodReplica p = new PodReplica(previous); p.markReady(); pods.add(p); }
        log.info(() -> "reverted to " + previous + " (NOTE: external state NOT reverted)");
    }

    public String currentVersion() { return pods.get(0).getVersion(); }
    public List<String> history() { return new ArrayList<>(revisionHistory); }
}
