package com.bank.rollout;

import java.math.BigDecimal;
import java.util.logging.*;

public class RolloutDemo {
    private static final Logger log = Logger.getLogger(RolloutDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        RolloutManager mgr = new RolloutManager(4, 1, 0, "v5"); // zero-downtime config
        SchemaState db = new SchemaState();

        // Deploy v6: ships new image AND a forward DB migration
        mgr.rollingUpdate("v6");
        db.applyV6Migration();   // migration runs during/with the release
        log.info("v6 live; a transfer runs fine under v6");
        rajesh.debit(new BigDecimal("50000"));
        priya.credit(new BigDecimal("50000"));

        // v6 has a fee bug -> roll back the IMAGE
        mgr.undo();
        log.info("current image: " + mgr.currentVersion() + ", history=" + mgr.history());

        // But the DB migration persisted -> old v5 code insert fails
        boolean ok = db.insertTradeFromOldCode();
        if (!ok) {
            log.severe("ROLLBACK TRAP: v5 code cannot insert — fee_currency NOT NULL column still exists");
        } else {
            log.info("insert ok");
        }
    }
}
