# k8s/deployment.yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: transfer-service
spec:
  replicas: 4
  revisionHistoryLimit: 10        # keep 10 old ReplicaSets for rollback
  progressDeadlineSeconds: 120    # mark rollout failed if stuck > 2m
  strategy:
    type: RollingUpdate
    rollingUpdate:
      maxSurge: 1                 # one extra Pod during update
      maxUnavailable: 0           # never drop below desired -> zero downtime
  template:
    spec:
      containers:
        - name: transfer
          image: nbi/transfer-service:v6
          readinessProbe:
            httpGet: { path: /actuator/health/readiness, port: 8080 }
